"""Merkle tree construction over event lines and snapshot persistence.

Rules:
  * leaves are sha256 of each raw event line (no trailing newline)
  * internal nodes are sha256(left || right)
  * an odd node at any level is paired with a duplicate of itself
"""

import hashlib
import json
import os
import re


def leaf_hash(line):
    """sha256 digest (bytes) of one raw event line."""
    if isinstance(line, str):
        line = line.encode("utf-8")
    return hashlib.sha256(line).digest()


def hash_pair(left, right):
    return hashlib.sha256(left + right).digest()


def read_lines(events_path, count=None):
    """Return the first `count` raw event lines (newline stripped)."""
    with open(events_path, "rb") as f:
        data = f.read()
    lines = [l for l in data.split(b"\n") if l]
    if count is not None:
        lines = lines[:count]
    return lines


def build_levels(lines):
    """Build all levels of the Merkle tree, leaves first.

    Returns a list of levels; levels[0] are the leaf hashes and
    levels[-1][0] is the root. Odd levels are padded with a duplicate of
    the last node during pairing (the stored level stays unpadded).
    """
    if not lines:
        raise ValueError("cannot build a Merkle tree over zero events")
    level = [leaf_hash(line) for line in lines]
    levels = [level]
    while len(level) > 1:
        if len(level) % 2 == 1:
            level = level + [level[-1]]
        level = [hash_pair(level[i], level[i + 1]) for i in range(0, len(level), 2)]
        levels.append(level)
    return levels


def merkle_root(lines):
    """Hex root of the Merkle tree over the given event lines."""
    return build_levels(lines)[-1][0].hex()


_SNAP_RE = re.compile(r"snap-(\d+)\.json$")


def snapshot_path(snapshots_dir, seq):
    return os.path.join(snapshots_dir, "snap-%d.json" % seq)


def create_snapshot(events_path, snapshots_dir, count=None, seq=1):
    """Compute the root over the first `count` events and write snap-<seq>.json."""
    os.makedirs(snapshots_dir, exist_ok=True)
    lines = read_lines(events_path)
    if count is None:
        count = len(lines)
    elif count > len(lines):
        raise ValueError("snapshot count %d exceeds %d available events" % (count, len(lines)))
    root = merkle_root(lines[:count]) if count else None
    snap = {"root": root, "count": count}
    path = snapshot_path(snapshots_dir, seq)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(snap, f, indent=2, sort_keys=True)
        f.write("\n")
    return path


def load_snapshot(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def list_snapshots(snapshots_dir):
    """All snapshots as (seq, path) sorted by seq."""
    if not os.path.isdir(snapshots_dir):
        return []
    found = []
    for name in os.listdir(snapshots_dir):
        m = _SNAP_RE.fullmatch(name)
        if m:
            found.append((int(m.group(1)), os.path.join(snapshots_dir, name)))
    return sorted(found)


def find_snapshot(snapshots_dir, min_count):
    """Newest snapshot covering at least `min_count` events, or None."""
    best = None
    for _, path in list_snapshots(snapshots_dir):
        snap = load_snapshot(path)
        if snap["count"] >= min_count and (best is None or snap["count"] < best["count"]):
            best = snap
            best["path"] = path
    return best

