"""Append-only writer for consent events (one JSON object per line)."""

import json
import os
from datetime import datetime, timezone

from .snapshot import create_snapshot


def utc_now():
    return datetime.now(timezone.utc).isoformat()


class ConsentWriter:
    """Appends consent events to an append-only log.

    Every `snapshot_every` appends a Merkle snapshot is written to
    `snapshots_dir`. `finalize()` snapshots any trailing tail so that the
    latest state is always provable.
    """

    def __init__(self, events_path="events.log", snapshots_dir="snapshots", snapshot_every=1000):
        self.events_path = events_path
        self.snapshots_dir = snapshots_dir
        self.snapshot_every = max(1, int(snapshot_every))
        self.count = self._count_lines()

    def _count_lines(self):
        if not os.path.exists(self.events_path):
            return 0
        with open(self.events_path, "rb") as f:
            return sum(1 for _ in f)

    def append(self, subject, purpose, action, ts=None):
        """Append one consent event; returns the event dict."""
        event = {
            "subject": subject,
            "purpose": purpose,
            "action": action,
            "ts": ts or utc_now(),
        }
        line = json.dumps(event, sort_keys=True, separators=(",", ":"))
        with open(self.events_path, "a", encoding="utf-8") as f:
            f.write(line + "\n")
            f.flush()
            os.fsync(f.fileno())
        self.count += 1
        if self.count % self.snapshot_every == 0:
            self.snapshot()
        return event

    def snapshot(self):
        """Snapshot the current log at seq = ceil(count / snapshot_every)."""
        seq = -(-self.count // self.snapshot_every)  # ceil division
        return create_snapshot(
            self.events_path, self.snapshots_dir, count=self.count, seq=seq
        )

    def finalize(self):
        """Snapshot the tail if the last event isn't already covered."""
        if self.count == 0:
            return None
        return self.snapshot()

