"""Inclusion proofs for individual events against Merkle snapshots.

An audit path entry is {"sibling": <hex>, "is_left": bool}, where
"is_left" means the sibling hash is concatenated on the left of the
running hash. The side can be derived from the event index during proof
generation, and is stored explicitly so verification needs only
(leaf, audit path, root).
"""

import json
import os

from .snapshot import build_levels, find_snapshot, leaf_hash, read_lines


def inclusion_proof(k, events_path, snapshot):
    """Audit path for event k (1-based) against a snapshot dict.

    Returns a JSON-serialisable proof dict with leaf, root, count and
    audit path. The snapshot's count bounds the tree so proofs stay valid
    even if more events were appended afterwards.
    """
    count = snapshot["count"]
    if not 1 <= k <= count:
        raise IndexError("event %d out of range for snapshot with %d events" % (k, count))
    lines = read_lines(events_path)[:count]
    if len(lines) < count:
        raise ValueError("log has %d events, snapshot claims %d" % (len(lines), count))
    levels = build_levels(lines)

    idx = k - 1
    audit = []
    for level in levels[:-1]:
        padded = list(level) + ([level[-1]] if len(level) % 2 == 1 else [])
        sib_idx = idx ^ 1
        audit.append({"sibling": padded[sib_idx].hex(), "is_left": sib_idx % 2 == 0})
        idx //= 2

    return {
        "event_index": k,
        "count": count,
        "leaf": leaf_hash(lines[k - 1]).hex(),
        "root": levels[-1][0].hex(),
        "audit_path": audit,
        "snapshot": os.path.basename(snapshot.get("path", "")) or None,
    }


def verify_proof(leaf, proof, root):
    """Replay an audit path from `leaf` and compare against `root`.

    Returns True iff the recomputed root matches. Never raises on
    malformed input; malformed input simply fails verification.
    """
    try:
        current = bytes.fromhex(leaf)
    except (TypeError, ValueError):
        return False
    if len(current) != 32:
        return False
    for step in proof:
        try:
            if isinstance(step, dict):
                sibling_hex, is_left = step["sibling"], bool(step["is_left"])
            else:
                sibling_hex, is_left = step, False
            sibling = bytes.fromhex(sibling_hex)
        except (KeyError, TypeError, ValueError):
            return False
        if len(sibling) != 32:
            return False
        current = (
            __import__("hashlib").sha256(sibling + current).digest()
            if is_left
            else hash_pair_local(current, sibling)
        )
    try:
        return current.hex() == root.lower()
    except (TypeError, AttributeError):
        return False


def hash_pair_local(left, right):
    import hashlib

    return hashlib.sha256(left + right).digest()


def save_proof(proof, path):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(proof, f, indent=2, sort_keys=True)
        f.write("\n")
    return path


def load_proof(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def prove(k, events_path, snapshots_dir):
    """Convenience: pick the newest snapshot covering event k and prove it."""
    snap = find_snapshot(snapshots_dir, k)
    if snap is None:
        raise LookupError("no snapshot covering event %d in %r" % (k, snapshots_dir))
    return inclusion_proof(k, events_path, snap), snap

